// 네이버 지도 API로 매장 검색
// 키워드 목록 (사업부별)
const keywords = [
  { keyword: '전주 카페', business_unit: 'webdev', type: 'cafe' },
  { keyword: '전주 음식점', business_unit: 'webdev', type: 'restaurant' },
  { keyword: '전주 미용실', business_unit: 'webdev', type: 'beauty' },
  { keyword: '전주 학원', business_unit: 'webdev', type: 'academy' },
  { keyword: '완주 펜션', business_unit: 'pension', type: 'pension' },
  { keyword: '전주 인테리어', business_unit: 'cnc', type: 'interior' },
  { keyword: '전주 카페 인테리어', business_unit: 'cnc', type: 'cafe_interior' }
];

// 오늘 실행할 키워드 (로테이션)
const today = new Date().getDay(); // 0~6
const todayKeywords = keywords.filter((_, i) => i % 7 === today || keywords.length <= 7);

return todayKeywords.map(k => ({ json: k }));

// 검색 결과 파싱 + 홈페이지 없는 곳 필터링
const items = $input.first().json.items || [];
const keyword = $input.first().json.keyword;
const business_unit = $input.first().json.business_unit;

const leads = items.map(item => {
  // HTML 태그 제거
  const name = item.title.replace(/<[^>]*>/g, '');
  const hasWebsite = item.link && item.link.trim() !== '';

  return {
    json: {
      name: name,
      company: name,
      phone: item.telephone || '',
      address: item.roadAddress || item.address || '',
      website_url: item.link || '',
      website_status: hasWebsite ? 'exists' : 'none',
      business_unit: business_unit,
      source: 'naver_map',
      interest: [keyword],
      need: hasWebsite ? '리뉴얼 가능' : '홈페이지 없음 — 제작 필요',
      score: hasWebsite ? 5 : 20,  // 홈페이지 없는 곳이 더 높은 스코어
      customer_type: 'b2c'
    }
  };
});

return leads;

